  "quiz": [
    {
      "id": "q1",
      "q": "十八年前，在断魂坡出事的是哪一家镖局？",
      "options": [
        {
          "key": "A",
          "text": "长风镖局"
        },
        {
          "key": "B",
          "text": "平安镖局"
        },
        {
          "key": "C",
          "text": "飞虎镖局"
        },
        {
          "key": "D",
          "text": "顺风镖局"
        }
      ],
      "answer": "C",
      "clue": "sg_store_4",
      "explain": "库房樟木箱底的旧镖旗上绣着一只扑地的虎，旗里裹着断魂坡的镖线图：出事的是飞虎镖局。"
    },
    {
      "id": "q2",
      "q": "断魂坡那趟出事的镖，押送的是什么？",
      "options": [
        {
          "key": "A",
          "text": "一批官家的盐引"
        },
        {
          "key": "B",
          "text": "二十车药材"
        },
        {
          "key": "C",
          "text": "一口黑漆镖箱"
        },
        {
          "key": "D",
          "text": "八千两官饷"
        }
      ],
      "answer": "D",
      "clue": "sg_shrine_4",
      "explain": "祠堂牌位背后的字条记着十八年前腊月二十三的八千两和二十三人。"
    },
    {
      "id": "q3",
      "q": "祠堂最底一排那二十三块没有刻字的白木牌，指的是谁？",
      "options": [
        {
          "key": "A",
          "text": "长风镖局历任走失的镖师"
        },
        {
          "key": "B",
          "text": "断魂坡一役中没有回来的二十三个人"
        },
        {
          "key": "C",
          "text": "镖局里二十三位老主顾"
        },
        {
          "key": "D",
          "text": "二十三位已故的趟子手"
        }
      ],
      "answer": "B",
      "clue": "sg_shrine_1",
      "explain": "白木牌的数目与断魂坡旧案的二十三人相符，牌后小香炉里的黄纸上写着断魂坡三个字。"
    },
    {
      "id": "q4",
      "q": "戚红缨的亲生父亲戚大山，当年是做什么的？",
      "options": [
        {
          "key": "A",
          "text": "州府的差役"
        },
        {
          "key": "B",
          "text": "长风镖局的账房"
        },
        {
          "key": "C",
          "text": "山里的猎户"
        },
        {
          "key": "D",
          "text": "飞虎镖局的镖师"
        }
      ],
      "answer": "D",
      "clue": "sg_qi_4",
      "explain": "戚红缨枕芯里那张名册残页，第十七行写着戚大山，页首的虎头印与旧镖旗上扑地的虎同出一处：那是飞虎镖局的镖师名册。"
    },
    {
      "id": "q5",
      "q": "吴百川当年出事之后，镖局对外是怎么交代的？",
      "options": [
        {
          "key": "A",
          "text": "染了时疫，病重不治"
        },
        {
          "key": "B",
          "text": "押镖途中遇匪殒命"
        },
        {
          "key": "C",
          "text": "辞镖离乡后下落不明"
        },
        {
          "key": "D",
          "text": "酒后失足坠崖"
        }
      ],
      "answer": "B",
      "clue": "sg_wu_4",
      "explain": "烧掉半边的抚恤单上残存着吴百川、遇匪殒命、抚银三十两。"
    },
    {
      "id": "q6",
      "q": "镖局账上每年腊月二十三都有一笔不入正册的款子，收款人一栏写的是什么字？",
      "options": [
        {
          "key": "A",
          "text": "官"
        },
        {
          "key": "B",
          "text": "万"
        },
        {
          "key": "C",
          "text": "黑"
        },
        {
          "key": "D",
          "text": "风"
        }
      ],
      "answer": "C",
      "clue": "sg_zhang_4",
      "explain": "张铁算的底册里，每年腊月二十三那一行的收款人都只写一个黑字，十八年没有断过。"
    }
  ],
